// Models safely turn the API's JSON into null-safe Dart objects.
DateTime? _date(dynamic value) => value == null ? null : DateTime.tryParse(value.toString());
class User { User({required this.id, required this.fullName, required this.email, this.createdAt}); final String id, fullName, email; final DateTime? createdAt; factory User.fromJson(Map<String,dynamic> j)=>User(id:j['id']??'',fullName:j['fullName']??'',email:j['email']??'',createdAt:_date(j['createdAt'])); Map<String,dynamic> toJson()=>{'id':id,'fullName':fullName,'email':email,'createdAt':createdAt?.toIso8601String()}; }
class Project { Project({required this.id,required this.name,this.description,required this.status,this.startDate,this.endDate,this.createdAt,required this.taskCount}); final String id,name,status; final String? description; final DateTime? startDate,endDate,createdAt; final int taskCount; factory Project.fromJson(Map<String,dynamic> j)=>Project(id:j['id']??'',name:j['name']??'',description:j['description'],status:j['status']??'NOT_STARTED',startDate:_date(j['startDate']),endDate:_date(j['endDate']),createdAt:_date(j['createdAt']),taskCount:j['taskCount']??0); Map<String,dynamic> toJson()=>{'id':id,'name':name,'description':description,'status':status,'startDate':startDate?.toIso8601String(),'endDate':endDate?.toIso8601String(),'createdAt':createdAt?.toIso8601String(),'taskCount':taskCount}; }
class Task { Task({required this.id,required this.projectId,required this.name,this.description,required this.priority,required this.status,this.dueDate,this.createdAt}); final String id,projectId,name,priority,status; final String? description; final DateTime? dueDate,createdAt; factory Task.fromJson(Map<String,dynamic> j)=>Task(id:j['id']??'',projectId:j['projectId']??'',name:j['name']??'',description:j['description'],priority:j['priority']??'MEDIUM',status:j['status']??'PENDING',dueDate:_date(j['dueDate']),createdAt:_date(j['createdAt'])); Map<String,dynamic> toJson()=>{'id':id,'projectId':projectId,'name':name,'description':description,'priority':priority,'status':status,'dueDate':dueDate?.toIso8601String(),'createdAt':createdAt?.toIso8601String()}; }
class DashboardStats { DashboardStats({required this.totalProjects,required this.totalTasks,required this.completedTasks,required this.pendingTasks,required this.projectsInProgress}); final int totalProjects,totalTasks,completedTasks,pendingTasks,projectsInProgress; factory DashboardStats.fromJson(Map<String,dynamic> j)=>DashboardStats(totalProjects:j['totalProjects']??0,totalTasks:j['totalTasks']??0,completedTasks:j['completedTasks']??0,pendingTasks:j['pendingTasks']??0,projectsInProgress:j['projectsInProgress']??0); Map<String,dynamic> toJson()=>{'totalProjects':totalProjects,'totalTasks':totalTasks,'completedTasks':completedTasks,'pendingTasks':pendingTasks,'projectsInProgress':projectsInProgress}; }
class Pagination { Pagination({required this.page,required this.limit,required this.total,required this.totalPages}); final int page,limit,total,totalPages; factory Pagination.fromJson(Map<String,dynamic> j)=>Pagination(page:j['page']??1,limit:j['limit']??20,total:j['total']??0,totalPages:j['totalPages']??1); Map<String,dynamic> toJson()=>{'page':page,'limit':limit,'total':total,'totalPages':totalPages}; }
